#[derive(Clone, Debug)]
pub struct SmeltRegExp {
    id: usize,
    source: String,
    flags: String,
    last_index: ::std::rc::Rc<::std::cell::RefCell<usize>>,
}

impl PartialEq for SmeltRegExp { fn eq(&self, other: &Self) -> bool { self.source == other.source && self.flags == other.flags && *self.last_index.borrow() == *other.last_index.borrow() } }

impl SmeltRegExp {
    /// Construct a JavaScript-like RegExp value with shared lastIndex state.
    pub fn new(source: String, flags: String) -> Self {
        Self { id: smelt_next_object_id(), source, flags, last_index: ::std::rc::Rc::new(::std::cell::RefCell::new(0)) }
    }
    /// Return true when this RegExp has a flag.
    pub fn has_flag(&self, flag: char) -> bool {
        self.flags.chars().any(|value| value == flag)
    }
    /// Compile the Rust regex equivalent for this JavaScript RegExp.
    fn compiled(&self) -> fancy_regex::Regex {
        self.try_compiled().expect("regex compile failed")
    }
    /// Try to compile the Rust regex equivalent for this JavaScript RegExp.
    fn try_compiled(&self) -> Option<fancy_regex::Regex> {
        let mut prefix = String::new();
        if self.has_flag('i') { prefix.push('i'); }
        if self.has_flag('m') { prefix.push('m'); }
        if self.has_flag('s') { prefix.push('s'); }
        let translated_source = self.source.replace("[^]", "(?s:.)");
        let pattern = if prefix.is_empty() { translated_source } else { format!("(?{prefix}){translated_source}") };
        fancy_regex::Regex::new(&pattern).ok()
    }
    /// Match a string with JavaScript String.prototype.match semantics.
    pub fn match_string(&self, haystack: &str) -> Option<Vec<String>> {
        let regex = self.try_compiled()?;
        if self.has_flag('g') {
            let matches = regex.find_iter(haystack).filter_map(Result::ok).map(|value| value.as_str().to_owned()).collect::<Vec<_>>();
            if matches.is_empty() { None } else { Some(matches) }
        }
        else {
            let captures = regex.captures(haystack).ok().flatten()?;
            Some((0..captures.len()).map(|index| captures.get(index).map_or(String::new(), |value| value.as_str().to_owned())).collect::<Vec<_>>())
        }
    }
    /// Split a string with JavaScript RegExp separator semantics.
    pub fn split_string(&self, haystack: &str) -> Vec<String> {
        let Some(regex) = self.try_compiled() else { return vec![haystack.to_owned()]; };
        regex.split(haystack).filter_map(Result::ok).map(str::to_owned).collect::<Vec<_>>()
    }
    /// Replace matches with JavaScript RegExp-aware String.prototype.replace semantics.
    pub fn replace_string(&self, haystack: &str, replacement: &str, force_all: bool) -> String {
        let Some(regex) = self.try_compiled() else { return haystack.to_owned(); };
        let replace_all = force_all || self.has_flag('g');
        if replace_all {
            let mut output = String::new();
            let mut last_end = 0usize;
            for matched in regex.find_iter(haystack).filter_map(Result::ok) {
                output.push_str(&haystack[last_end..matched.start()]);
                output.push_str(replacement);
                last_end = matched.end();
            }
            output.push_str(&haystack[last_end..]);
            output
        }
        else if let Ok(Some(matched)) = regex.find(haystack) {
            format!("{}{}{}", &haystack[..matched.start()], replacement, &haystack[matched.end()..])
        } else {
            haystack.to_owned()
        }
    }
    /// Execute this RegExp and return a JavaScript-like match object.
    pub fn exec(&self, haystack: &str) -> Option<SmeltUnknown> {
        let regex = self.compiled();
        let start = if self.has_flag('g') || self.has_flag('y') { *self.last_index.borrow() } else { 0 };
        let suffix = haystack.get(start..).unwrap_or("");
        let captures = regex.captures(suffix).ok().flatten()?;
        let matched = captures.get(0)?;
        if self.has_flag('y') && matched.start() != 0 { *self.last_index.borrow_mut() = 0; return None; }
        if self.has_flag('g') || self.has_flag('y') { *self.last_index.borrow_mut() = start + matched.end(); }
        let mut object = ::std::collections::HashMap::new();
        for index in 0..captures.len() { if let Some(value) = captures.get(index) { object.insert(index.to_string(), SmeltUnknown::String(value.as_str().to_owned())); } else { object.insert(index.to_string(), SmeltUnknown::Null); } }
        let mut groups = ::std::collections::HashMap::new();
        for name in regex.capture_names().flatten() { let value = captures.name(name).map_or(SmeltUnknown::Null, |value| SmeltUnknown::String(value.as_str().to_owned())); groups.insert(name.to_owned(), value.clone()); let mut snake = String::new(); for (index, ch) in name.chars().enumerate() { if ch.is_ascii_uppercase() { if index > 0 { snake.push('_'); } snake.push(ch.to_ascii_lowercase()); } else { snake.push(ch); } } groups.insert(snake, value); }
        object.insert("groups".to_owned(), SmeltUnknown::Object(SmeltObject::new(groups)));
        object.insert("index".to_owned(), SmeltUnknown::Number((start + matched.start()) as f64));
        object.insert("input".to_owned(), SmeltUnknown::String(haystack.to_owned()));
        Some(SmeltUnknown::Object(SmeltObject::new(object)))
    }
    /// Return indexed match records for JavaScript String.prototype.matchAll.
    pub fn match_all_indices(&self, haystack: &str) -> Vec<SmeltRecord<String, f64>> {
        let Some(regex) = self.try_compiled() else { return Vec::new(); };
        regex.find_iter(haystack).filter_map(Result::ok).map(|matched| SmeltRecord::from([("index".to_owned(), matched.start() as f64)])).collect::<Vec<_>>()
    }
    /// Test this RegExp against a string with JavaScript lastIndex updates.
    pub fn test(&self, haystack: &str) -> bool {
        self.exec(haystack).is_some()
    }
}

